import { Suspense } from 'react'
import { RevenueChart, RevenueChartSkeleton } from './RevenueChart'
import { LatestInvoices, LatestInvoicesSkeleton } from './LatestInvoices'
import { CardStats, CardStatsSkeleton } from './CardStats'

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default function Page() {
  const dataPromise = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChart dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoices dataPromise={dataPromise} />
      </Suspense>
    </main>
  )
}

