import type { DashboardData } from './page'

export async function CardStats({
  dataPromise,
}: {
  dataPromise: Promise<DashboardData>
}) {
  const { totalRevenue, totalInvoices } = await dataPromise

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>&nbsp;</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>&nbsp;</p>
      </div>
    </div>
  )
}

